update intel.demand_themes set base_demand_score=.88,confidence=.92,active_to='2026-09-30',
 metadata=metadata||jsonb_build_object('evidence_source','Greek Ministry school start 11 September 2026; Skroutz Back-to-School campaign 20 Aug–6 Sep 2026','evidence_checked_at','2026-08-26','contract_version','v10'),updated_at=now()
where slug like 'bts-%' or slug='back-to-school-2026';

on conflict(slug) do update set name=excluded.name,theme_type=excluded.theme_type,market=excluded.market,active_from=excluded.active_from,peak_date=excluded.peak_date,active_to=excluded.active_to,semantic_brief=excluded.semantic_brief,base_demand_score=excluded.base_demand_score,confidence=excluded.confidence,status='active',metadata=excluded.metadata,updated_at=now();
